function plano(s) {
  return String(s || '').toLowerCase()
    .replace(/á/g, 'a').replace(/é/g, 'e').replace(/í/g, 'i')
    .replace(/ó/g, 'o').replace(/ú/g, 'u').replace(/ñ/g, 'n');
}
const motivo = plano(query);
const canales = {
  dosep: { email: 'dosep@circulomedicodelnorte.com.ar', uso: 'Cobertura DOSEP, autorizaciones y gestiones de obra social' },
  socios: { email: 'socios@circulomedicodelnorte.com.ar', uso: 'Estado de socio, aranceles, trámites de asociación y cuota social' },
  convenios: { email: 'convenios@circulomedicodelnorte.com.ar', uso: 'Propuestas, acuerdos y convenios' },
  administracion: { email: 'administracion@circulomedicodelnorte.com.ar', uso: 'Temas contables y administración interna' },
  general: { email: 'socios@circulomedicodelnorte.com.ar', telefono: '(+54) 02656-470428', uso: 'Consultas generales' }
};
let key = 'general';
if (motivo.includes('dosep') || motivo.includes('obra social') || motivo.includes('autoriz')) key = 'dosep';
else if (motivo.includes('socio') || motivo.includes('asoci') || motivo.includes('cuota') || motivo.includes('arancel')) key = 'socios';
else if (motivo.includes('convenio') || motivo.includes('acuerdo')) key = 'convenios';
else if (motivo.includes('admin') || motivo.includes('contab') || motivo.includes('factura')) key = 'administracion';
return JSON.stringify({ motivo_detectado: key, ...canales[key], formularios_desde: 'web@circulomedicodelnorte.com.ar', nota: 'No sacar turnos ni dar atención médica; solo derivar.' });

const ctx = $('Extraer mensaje y teléfono').first().json;
const agentOut = $input.first().json;
let botReply = agentOut.output || agentOut.text || agentOut.response || 'Lo siento, no pude procesar tu consulta. Por favor llamá al 02656-470428.';
botReply = String(botReply).replace(/###\s*/g, '').replace(/##\s*/g, '').replace(/#\s*/g, '').trim();
if (botReply.length > 1600) botReply = botReply.substring(0, 1550) + '...';
return [{ json: { phoneId: ctx.phoneId, conversation_id: ctx.conversation_id, botReply } }];
